local _order = {8,15,10,13,20,4,12,19,14,18,5,17,3,16,2,21,11,9,7,6,1}
local _alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local _lookup = {}
for k=1,#_alphabet do _lookup[_alphabet:byte(k)] = k-1 end
local function _decode(encoded, index)
    local acc, bits, count, out = 0, 0, 0, {}
    for pos=1,#encoded do
        local ch = encoded:byte(pos)
        if ch == 61 then break end
        local val = _lookup[ch]
        if val ~= nil then
            acc = acc*64+val
            bits = bits+6
            if bits >= 8 then
                bits=bits-8
                count=count+1
                local unit = math.floor(acc/(2^bits))%256
                acc = acc%(2^bits)
                out[count] = string.char((unit-((index*67+count*29+math.floor(count/13)*11+103)%256))%256)
            end
        end
    end
    return table.concat(out)
end
local _parts = {}
for i=1,#_order do
    _parts[i] = _decode(_data[_order[i]], i)
end
_data, _order, _lookup = nil, nil, nil
local _code = table.concat(_parts)
_parts = nil
local _run, _err = loadstring(_code, '@pomoshnik.lua')
_code = nil
if not _run then error('[Помощник онлайн] ' .. tostring(_err)) end
